  pumpkin: (x = 50) => `<path d="M${x - 14},84 Q${x - 16},70 ${x - 4},70 Q${x},64 ${x + 6},70 Q${x + 16},70 ${x + 14},84Z" fill="${P.orange}" ${OL}/><path d="M${x - 8},72 V84 M${x},70 V84 M${x + 8},72 V84" stroke="${P.ink}" stroke-width=".4" opacity=".5"/><path d="M${x},70 v-5" stroke="${P.green}" stroke-width="1.6"/><path d="M${x + 14},78 l8,-4 l-2,8Z M${x - 20},82 l4,-6 l2,6Z" fill="${P.orange}" ${OL}/><path d="M${x - 4},76 q2,4 6,0" fill="none" stroke="${P.yellow}" stroke-width="1.2"/><circle cx="${x + 12}" cy="82" r="1.6" fill="${P.red}"/><circle cx="${x - 10}" cy="78" r="1.2" fill="${P.yellow}"/>`,
