  ironbox: (x = 50) => `<path d="M${x - 12},84 L${x - 10},72 H${x + 12} L${x + 14},84Z" fill="${P.grey}" ${OL}/><path d="M${x - 6},72 V66 H${x + 8} V72" fill="${P.grey}" ${OL}/><path d="M${x - 4},70 h8" stroke="${P.ink}" stroke-width="1.6"/>` + [[-4, 78], [2, 76], [6, 80]].map(([d, y]) => `<circle cx="${x + d}" cy="${y}" r="1.6" fill="${P.orange}"/>`).join("") + JUNK.pile(x + 22, "black", 8, 5) + JUNK.smoke(x + 2, 60, "grey").replace(/opacity="\.55"/g, 'opacity=".35"'),
  fishscales: (x = 50) => `<path d="M${x - 16},84 Q${x - 12},76 ${x},78 Q${x + 12},76 ${x + 16},84Z" fill="${P.sky}" opacity=".8" ${OL}/>` + [[-10, 80], [-4, 78], [2, 79], [8, 80], [-2, 82], [6, 83]].map(([d, y]) => `<circle cx="${x + d}" cy="${y}" r="1.2" fill="${P.white}" ${OL}/>`).join("") + `<path d="M${x + 14},78 q6,-6 10,0 q-4,-2 -10,0Z M${x + 24},78 l4,-3 v6Z" fill="${P.grey}" ${OL}/><ellipse cx="${x - 20}" cy="84" rx="6" ry="1.6" fill="${P.sky}" opacity=".7"/>`,
  // Animals and people who use the above
  cow: (x = 50, c = "white") => `<g transform="translate(${x} 84)"><path d="M-18,0 V-12 M-12,0 V-12 M10,0 V-12 M16,0 V-12" stroke="${col(c)}" stroke-width="3.4" stroke-linecap="round"/><path d="M-18,0 V-12 M-12,0 V-12 M10,0 V-12 M16,0 V-12" stroke="${P.ink}" stroke-width="4.4" stroke-linecap="round" opacity=".12"/><path d="M-20,-12 Q-22,-30 -8,-30 H12 Q22,-30 20,-12Z" fill="${col(c)}" ${OL}/><path d="M18,-28 Q22,-22 20,-16 Q24,-12 30,-14 Q32,-26 24,-30Z" fill="${col(c)}" ${OL}/><path d="M22,-30 q-2,-6 2,-7 M28,-30 q4,-5 1,-8" fill="none" stroke="${P.ink}" stroke-width="1"/><circle cx="26" cy="-24" r=".9" fill="${P.ink}"/><path d="M-20,-14 q-4,8 -2,14" fill="none" stroke="${P.ink}" stroke-width="1"/><path d="M-10,-26 q4,4 8,0 M2,-20 q3,3 6,0" fill="none" stroke="${P.grey}" stroke-width="2"/><ellipse cx="-4" cy="-12" rx="6" ry="3" fill="${P.pink}" ${OL}/><path d="M24,-12 h12" stroke="${P.kaapi}" stroke-width=".8"/></g>`,
  dog: (x = 50, c = "beige") => `<g transform="translate(${x} 84)"><path d="M-14,0 Q-16,-12 -4,-12 H10 Q18,-12 16,0Z" fill="${col(c)}" ${OL}/><path d="M10,-12 Q12,-18 18,-18 Q24,-18 24,-12 Q22,-6 16,-6Z" fill="${col(c)}" ${OL}/><path d="M18,-18 l-2,-5 l4,3" fill="${col(c)}" ${OL}/><circle cx="21" cy="-13" r=".8" fill="${P.ink}"/><path d="M-14,-4 q-8,-6 -6,-14" fill="none" stroke="${col(c)}" stroke-width="2"/><path d="M-10,0 v-3 M0,0 v-3 M8,0 v-3" stroke="${P.ink}" stroke-width=".6"/><path d="M-6,-12 q6,-6 12,0" fill="none" stroke="${P.ink}" stroke-width=".4" stroke-dasharray="1 1"/></g>`,
